window.docContents[72].resolve({"/#Adic-Spaces-___-Lean-blueprint":{"contents":"This is the blueprint for the Adic-Spaces\nformalisation (Birkbeck) of Huber's theory of adic spaces — the foundations of\n-adic geometry and perfectoid spaces, following Wedhorn's notes. It develops\nHuber rings and Tate rings, the valuation spectrum , rings of\nintegral elements, the adic spectrum , Tate algebras, and (in\nprogress) the structure sheaf.\n\nEach node carries a (lean := …) reference to the actual declaration in the\n«Adic spaces» library, so Verso reads its completion status directly from Lean\n— green once the declaration is fully proved, blue while it still contains\nsorry. The dependency graph at the foot of the page records which results feed\ninto which.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Adic Spaces — Lean blueprint","id":"/#Adic-Spaces-___-Lean-blueprint"}});